SELECT CONCAT(c.c_first_name, ' ', c.c_last_name) AS full_name, CASE WHEN c.c_birth_year < 1927 THEN 'Young' WHEN c.c_birth_year BETWEEN 1927 AND 1988 THEN 'Middle' ELSE 'Old' END AS age_group, (wr.wr_return_amt * 3907.17) + wr.wr_return_tax - wr.wr_fee AS adjusted_return, CASE WHEN wr.wr_return_quantity > 91 THEN 'Bulk' ELSE 'Single' END AS return_type, c.c_first_sales_date_sk + 2451038 AS sales_date_shift, c.c_preferred_cust_flag = 'N' AS preferred_flag_match FROM web_returns wr INNER JOIN customer c ON wr.wr_refunded_customer_sk = c.c_customer_sk WHERE c.c_preferred_cust_flag = 'N'
